// Copies the approved site's static assets (CSS, JS, images, documents, media, robots, _headers)
// from ../public into public/. HTML pages are served by EmDash routes instead; _redirects is
// generated by build-redirects.mjs.
// Production builds (see site-env.mjs) replace the review site's robots.txt with one that allows crawling
// and names the sitemap, and drop the noindex header from _headers. The test site keeps both.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { PRODUCTION, ORIGIN } from './site-env.mjs';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const src = path.resolve(root, '../public');
const dest = path.join(root, 'public');
let n = 0;
for (const name of fs.readdirSync(src)) {
  if (name.endsWith('.html') || name === '_redirects') continue;
  fs.cpSync(path.join(src, name), path.join(dest, name), { recursive: true });
  n++;
}
console.log(`copied ${n} entries from ../public`);

if (PRODUCTION) {
  fs.writeFileSync(path.join(dest, 'robots.txt'), `User-agent: *\nDisallow: /_emdash/\n\nSitemap: ${ORIGIN}/sitemap.xml\n`);
  const headersPath = path.join(dest, '_headers');
  const lines = fs.readFileSync(headersPath, 'utf8').split(/\r?\n/);
  const kept = lines.filter((line) => !/^\s*X-Robots-Tag:/i.test(line));
  if (kept.length === lines.length) throw new Error('_headers: expected an X-Robots-Tag line to remove');
  fs.writeFileSync(headersPath, kept.join('\n'));
  console.log('production build: robots.txt allows crawling; X-Robots-Tag removed from _headers');
}
